{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "10",
      "explanation": "The SOQL query is constructed using string concatenation, which can lead to SOQL injection if the searchKey is not properly sanitized.",
      "remediation": "Use bind variables instead of string concatenation to prevent SOQL injection."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violations",
      "severity": "Medium",
      "file": "OpportunityStageService.cls",
      "lines": "1-10",
      "explanation": "The method does not enforce Field-Level Security (FLS) on the StageName field, potentially allowing users to update fields they shouldn't.",
      "remediation": "Use the getSObjectType().getDescribe().fields.getMap() method to enforce FLS on the StageName field."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violations",
      "severity": "Medium",
      "file": "ContactPhoneService.cls",
      "lines": "1-8",
      "explanation": "The method does not enforce Field-Level Security (FLS) on the Phone field before updating it.",
      "remediation": "Use the Schema.SObjectType.Contact.fields.Phone.isUpdateable() check to enforce FLS on the Phone field."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "FLS not enforced",
      "severity": "Medium",
      "file": "LeadQualifierService.cls",
      "lines": "10",
      "explanation": "The code updates the 'Status' field without enforcing Field-Level Security (FLS). This can allow users to modify fields they shouldn't have access to.",
      "remediation": "Use the 'SObject.get' and 'SObject.put' methods to enforce FLS."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection",
      "severity": "High",
      "file": "ContactSearchController.cls",
      "lines": "7-10",
      "explanation": "The SOQL query is vulnerable to SOQL injection as it directly interpolates the lastName parameter without any sanitization or escaping.",
      "remediation": "Use a parameterized SOQL query or escape the lastName parameter to prevent SOQL injection."
    }
  ]
}
